package com.example.familymenu.family.service;
import com.example.familymenu.common.exception.BusinessException; import com.example.familymenu.family.domain.*; import com.example.familymenu.family.repository.FamilyRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class FamilyServiceImpl implements FamilyService { private final FamilyRepository repo; public Family create(String n,String o){return repo.create(n,o);} public Family createForUser(String n,Long uid,String o){return repo.createForUser(n,uid,o);} public Family get(Long id){return repo.findById(id).orElseThrow(()->new BusinessException("家庭不存在: "+id));} public List<Family> mine(String nickname){return repo.findByUserNickname(nickname);} public List<Family> mineByUserId(Long uid){return repo.findByUserId(uid);} public List<FamilyMember> members(Long id){get(id);return repo.findMembers(id);} private String role(String r){String x=r==null||r.trim().isEmpty()?"MEMBER":r.toUpperCase();if(!Arrays.asList("OWNER","ADMIN","MEMBER").contains(x))throw new BusinessException("成员角色不合法");return x;} public FamilyMember addMember(Long id,String n,String r){get(id); String role=role(r); for(FamilyMember m: repo.findMembers(id)){if(m.getNickname().equals(n)) throw new BusinessException("该成员已在家庭中");} return repo.addMember(id,n,role);} public FamilyMember updateMemberRole(Long id,Long mid,String r){get(id);String role=role(r);if("OWNER".equals(role))throw new BusinessException("不能将成员设置为拥有者");if(!repo.updateMemberRole(id,mid,role))throw new BusinessException("成员不存在或不能修改拥有者");return repo.findMembers(id).stream().filter(m->m.getId().equals(mid)).findFirst().get();} public void removeMember(Long id,Long mid){get(id);if(!repo.removeMember(id,mid)) throw new BusinessException("成员不存在或不能移除拥有者");} public void delete(Long id){get(id);if(!repo.deleteFamily(id))throw new BusinessException("家庭删除失败");} }
